  ('eirexn', 'eirexn', '', '', '', 'Grundwortschatz Wienerisch', 'einrexen', '[{"kategorie": "wörtlich", "text": "\"in einem Rex-Glas konservieren\" (der Begriff „einrexen“ leitet sich direkt vom Markennamen REX ab. Dieser war [und ist] in Österreich synonym für spezielle Einmachgläser, ähnlich wie „Weck“ in Deutschland)"}, {"kategorie": "Küchenjargon", "text": "Lebensmittel einkochen, einlegen, haltbar machen, konservieren, in luftdichte Gläser/Tiegel abfüllen, [[eimagarian]]"}, {"kategorie": "fig.", "text": "\"etwas/jemanden innerlich wegpacken und vergessen\", \"für immer einmotten\", \"für immer entsorgen\", \"aus dem Kopf schlagen\""}]'::jsonb, 'Loss di eirexn!'),
  ('eimochsuppn', 'Eimochsuppn', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Einmachsuppe', '[{"kategorie": "wörtlich", "text": "\"Einmachsuppe\" (Determinativkompositum aus \"Einmach\"=\"helle Einbrenn/Mehlschwitze\" und \"Suppe\"=Brühe\")"}, {"kategorie": "Küchenjargon", "text": "\"Gebundene Suppe mit Kalbsknochenfond\" (Suppe, die mit einer Einmach [Einbrenn/Mehlschwitze] gebunden wird – oft mit Kalbsknochenfond als Basis, mild gewürzt, manchmal mit Gemüse, Reis oder Fleischstückchen), Kalbs-Einmachsuppe (mild gebundene Kalbssuppe), \"Velouté vom Kalb\" (französisch inspiriert – gebundene Brühe mit heller Roux)"}]'::jsonb, 'De Eimochsuppn woa säämich und wundaboa müüd im Gschmockn!'),
  ('saeaemich', 'säämich', '', '', '', 'Wiener Küche & Gaumenfreuden', 'sämig', '[{"kategorie": "wörtlich", "text": "\"sämig\" (vom mittelhochdeutschen \"seimig\"=\"dickflüssig\")"}, {"kategorie": "allg.", "text": "zähflüssig, dickflüssig, cremig"}]'::jsonb, ''),
  ('eigidschn', 'eigidschn', '', '', '', 'Grundwortschatz Wienerisch', 'eingitschen', '[{"kategorie": "wörtlich", "text": "\"eindellen\" (lautmalerisches Wort, das den dumpfen, weichen Klang imitiert, der beim Verursachen einer leichten Delle entsteht)"}, {"kategorie": "allg.", "text": "eindrücken, einbeulen, [[eindepschen]]"}]'::jsonb, 'Des Packl is eigidschd - hoffentlich is nix hii!'),
  ('gitschn', 'Gitschn', 'die', '', '', 'Grundwortschatz Wienerisch', 'Gitschen', '[{"kategorie": "wörtlich", "text": "\"junges Mädchen\" (vom mittelhochdeutschen \"gitze\"=\"Jungziege\")"}, {"kategorie": "allg.", "text": "\"Teenagermädchen\", \"Fräulein\", \"Plapperliese\", \"Schnatterziege\""}]'::jsonb, 'De Gitschn aum Neemtisch hod in zeen Minutn mea dazööd ois I in an Joa!'),
  ('gizi', 'Gizi', '', '', '', 'Grundwortschatz Wienerisch', 'Gizi, der/die', '[{"kategorie": "wörtlich", "text": "\"Gizi\" (vom mittelhochdeutschen \"gitze\"=\"Jungziege\")"}, {"kategorie": "allg. \"Gizi, die\"", "text": "\"Jungziege\", \"Zicklein\", \"Geißlein\""}, {"kategorie": "fig., \"Gizi, der\" - Kurzform für à\"Gizibart\"", "text": "\"innerer Zorn\" (stets mit begleitender Geste: man fährt sich mit der Hand ans Kinn und reibt daran – oft mit gespielter Ernsthaftigkeit - und ahmt damit einen Ziegenbart nach, den sogenannten à„Gizibart“, eine bildhafte Metapher für Ärger, der einem quasi wie ein Bart am Kinn „wächst“, je länger man schweigend schmollt oder grollt), \"innerer Groll\", \"Ärger\", \"schmollendes Schweigen\", \"unterdrückte Wut\""}]'::jsonb, 'De Gizi woan grod auf da Wööd und scho frech wia sunst wos!'),
  ('giziboad', 'Giziboad', 'der', '', '', 'Grundwortschatz Wienerisch', 'Gizibart', '[{"kategorie": "wörtlich", "text": "\"Ziegenbart\" (Determinativkompositum aus \"Gizi\"=\"Jungziege\" und \"Bart\"=\"Kinnbart\")"}, {"kategorie": "allg.", "text": "Kinnbart, Spitzbart, \"Goatee\" (nach unten spitz zulaufender Kinnbart - im Wienerischen auch eine bildhafte Metapher für Ärger, der einem quasi wie ein Ziegenbart am Kinn „wächst“, je länger man schweigend schmollt oder grollt)"}]'::jsonb, ''),
  ('eigroobm', 'eigroobm', '', '', '', 'Grundwortschatz Wienerisch', 'eingraben', '[{"kategorie": "wörtlich", "text": "\"eingraben\" (vom mittelhochdeutschen \"īngraben\"=\"eingraben\")"}, {"kategorie": "allg.", "text": "etwas einscharren, einbuddeln, in der Erde vergraben"}, {"kategorie": "in Bezug auf Personen", "text": "jemanden begraben, beisetzen, unter die Erde bringen"}, {"kategorie": "reflexiv", "text": "\"sich in etwas eingraben\", \"von etwas nicht genug bekommen\", \"auf etwas abfahren\", \"immer mehr von etwas wollen\""}]'::jsonb, 'Mit dem Schaas kaunnst di eigroobm lossn!'),
  ('eileffaen', 'eileffän', '', '', '', 'Grundwortschatz Wienerisch', 'einlöffeln', '[{"kategorie": "wörtlich", "text": "\"etwas löffelweise verabreichen\" (vom mittelhochdeutschen \"īnleffelen\"=\"einlöffeln\")"}, {"kategorie": "allg.", "text": "etwas löffelweise essen, löffelweise aufnehmen, löffelweise verabreichen"}, {"kategorie": "fig.", "text": "jemandem etwas löffelweise eintrichtern, einbläuen, einhämmern, \"reindrücken\""}, {"kategorie": "scherzhaft für", "text": "jemanden eingraben, einscharren, einbuddeln, begraben, beisetzen, \"unter die Erde bringen\""}]'::jsonb, 'Wea wiad ma de Suppn eileffän, waunn I amoi oid und schwoch bin?'),
