  ('einehaun', 'einehaun', '', '', '', 'Grundwortschatz Wienerisch', 'einehauen', '[{"kategorie": "wörtlich", "text": "\"reinhauen\" (Kompositum aus dem abtrennbaren Präfix [[eine]]=\"hinein\" und [[hauen]]=\"werfen\")"}, {"kategorie": "allg.", "text": "\"mit Appetit sehr viel und sehr schnell essen\", sich etwas reinschieben, sich etwas reinpacken"}, {"kategorie": "", "text": "jemanden schlagen, prügeln, [[dögeln]]"}, {"kategorie": "fig.", "text": "\"hart und schnell arbeiten\", \"sich reinhängen\", \"unermüdlich rackern\", [[hackln wiara Viech]]"}, {"kategorie": "Fußballerjargon", "text": "\"unfair und überhart spielen\", alles umsäbeln, niedermetzeln"}, {"kategorie": "reflexiv, allg.", "text": "\"sich ins Zeug legen\", sich anstrengen, mit vollem Einsatz dabei sein"}, {"kategorie": "scherzhaft für", "text": "schlemmen, völlen, sich den Wanst vollhauen"}]'::jsonb, 'De hod si voi eineghaud und uns oin zeigd, wias geed!'),
  ('mitgeebm', 'mitgeebm', '', '', '', 'Grundwortschatz Wienerisch', 'mitgeben', '[{"kategorie": "wörtlich", "text": "\"mitgeben\" (vom mittelhochdeutschen \"gëben\"=\"geben\")"}, {"kategorie": "allg.", "text": "\"jemandem etwas in die Hand drücken\", übergeben, aushändigen, mitnehmen lassen"}, {"kategorie": "fig.", "text": "jemandem etwas mit auf den Weg geben, jemandem etwas mit auf die Reise geben, jemandem eine Weisheit/einen Rat/einen Gedanken mit auf den Weg geben"}, {"kategorie": "scherzhaft für", "text": "\"jemandem eine Ohrfeige mit auf den Weg geben\", \"jemandem eine Watschen mit auf die Reise geben\""}]'::jsonb, 'Si hod eam sei gaunzes Zeig mitgeebm und gsoogd, ea soi nii wiida kumma!'),
