  ('faschiads', 'Faschiads', 'das', '', '', 'Wiener Fleischhauer-Slang', 'Faschiertes', '[{"kategorie": "wörtlich", "text": "\"durch den Fleischwolf gedrehtes Fleisch\" (vom französischen \"farce\"=\"aus gehacktem Fleisch hergestellte Füllung von Fleisch- oder Fischgerichten\")"}, {"kategorie": "Fleischhauerjargon", "text": "\"faschiertes Fleisch\", (Deutschland): \"Hackfleisch\", \"Gehacktes\""}]'::jsonb, 'Ausn Faschiadn moch ma heite Fleischlaawaln!'),
  ('fosching', 'Fosching', 'der', '', '', 'Grundwortschatz Wienerisch', 'Fasching', '[{"kategorie": "wörtlich", "text": "\"Fasching\" (vom mittelhochdeutschen \"vaschang\"=\"Ausschank des Fastentrunks\")"}, {"kategorie": "Deutschland", "text": "Fastnacht, Karneval, \"Narrenzeit\", \"fünfte Jahreszeit\""}]'::jsonb, 'Im Fosching deaf ma endlich so tuan, ois warad ma wea gaunz aundara!'),
  ('foschingskropfn', 'Foschingskropfn', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Faschingskrapfen', '[{"kategorie": "wörtlich", "text": "\"Faschingskrapfen\" (Determinativkompositum aus \"Fasching\"=\"Karneval\" und \"Krapfen\"=\"in Fett ausgebackene Germteigmehlspeise mit Marmeladefüllung)"}, {"kategorie": "allg.", "text": "Süßspeise mit Konfitürenfüllung (ähnlich dem \"Berliner Pfannkuchen\" bzw. \"Berliner\")"}]'::jsonb, 'Zu Fosching isst ma in Östarreich traditionell Foschingskropfn!'),
  ('foschingsdiinstog', 'Foschingsdiinstog', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Faschingsdienstag', '[{"kategorie": "wörtlich", "text": "\"Faschingsdienstag\" (Determinativkompositum aus \"Fasching\"=\"Karneval\" und \"Dienstag\"=\"2. Tag der Woche\")"}, {"kategorie": "allg.", "text": "\"letzter Tag im Fasching\" (der Tag vor dem Aschermittwoch), (Deutschland): Karnevalsdienstag, Fastnachtsdienstag, (USA/Frankreich): \"Mardi Gras\" (\"Fetter Dienstag\"), (Großbritannien) \"Pancake Tuesday\""}]'::jsonb, ''),
  ('oschamittwoch', 'Oschamittwoch', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Aschermittwoch', '[{"kategorie": "wörtlich", "text": "\"Aschermittwoch\" (vom mittelhochdeutschen \"aschemîtwoche\"=\"Aschermittwoch\")"}, {"kategorie": "rel.", "text": "\"erster Tag der 40-tägigen Fastenzeit vor Ostern\", \"der Tag nach dem Faschingsdienstag\", \"der Tag der Aschenauflegung\" (aus der Asche der im Vorjahr am Palmsonntag verbrannten Palmzweige wird den Gläubigen ein Aschenkreuz auf die Stirn gezeichnet – als Zeichen der Buße und Vergänglichkeit, begleitet von den Worten: ''Bedenke, Mensch, dass du Staub bist und wieder zum Staub wirst!'')"}]'::jsonb, 'Aum Oschamittwoch ruafd de Kiachn zu Besinnung, zu Buusse und zum Fostn auf!'),
  ('dreikeenigstoog', 'Dreikeenigstoog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Dreikönigstag', '[{"kategorie": "wörtlich", "text": "\"Dreikönigstag\" (aus dem mittelhochdeutschen \"drî künege tac\"=\"Dreikönigstag\")"}, {"kategorie": "rel.", "text": "\"Fest der Heiligen Drei Könige\" (6. Jänner), \"Epiphanie\" (\"Erscheinung des Herrn\", d.h. dass Jesus nicht nur für das Volk Israel, sondern für alle Völker der Welt gekommen ist), christlicher Feiertag (der an die Offenbarung Jesu Christi als Sohn Gottes gegenüber der Welt, insbesondere durch den Besuch der „Weisen aus dem Morgenland“ beim neugeborenen Jesuskind erinnert), \"Ankunft der drei Weisen aus dem Morgenland\" (wird insbesondere durch Sternsingeraktionen und Haussegnungen begangen, bei denen Kinder [verkleidet als die drei Könige Caspar, Melchior und Balthasar] in Gruppen von Haus zu Haus ziehen, Lieder singen und Häuser mit Kreidezeichen segnen (z. B. 20 ✝ C ✝ M ✝ B 25)"}]'::jsonb, 'De drei Weisn aus Moagnlaund bringan am Dreikeenigstoog iare Goobn: Goid, Weirauch und Myrre!'),
  ('poimsuundog', 'Poimsuundog', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Palmsonntag', '[{"kategorie": "wörtlich", "text": "\"Palmsonntag\" (vom mittelhochdeutschen \"palmesûn(tac)\"=\"Palmsonntag\")"}, {"kategorie": "rel.", "text": "katholischer Festtag (der sechste Sonntag der Fastenzeit ), \"der letzte Sonntag vor Ostern\", \"der Tag der Erwartung und Spannung\" (zwischen der freudigen Begrüßung Jesu als Messias und dem nahenden Leiden am Kreuz)"}]'::jsonb, 'De Kinda haum beim Umzug aum Poimsuundog bunt gschmickde Poimkatzalzweig troong!')
